-- Rifts World Book 3: England - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 4 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~278-england-npcs-a.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('zazshan', 'Zazshan', 'Zazshan', 'The Alien Intelligence behind Mrrlyn', 'rifts', 'Zllyphan (alien intelligence, energy being)', '10th level Ley Line Walker, Rune Master, Stone Master, Tattoo Master and Shifter/Summoner (special NPC R.C.C.)', 10, 'Miscreant', '120,000', NULL, NULL, '{"IQ":29,"ME":28,"MA":20,"PB":"3D6+6"}', NULL, NULL, 20000, 8000, 2000, NULL, 16, '{"attacks":6,"initiative":6,"strike":6}', 'Attacks per melee in energy form: six energy blasts, or five psionic attacks, or two magic attacks. The +6 to strike is with energy blasts. Automatic dodge, which works like a parry. +6 to save vs Horror Factor, +1 to spell strength, +2 on all saving throws (on top of attribute bonuses); impervious to mind control, even a vampire''s. P.S., P.P. and P.E.: not applicable. Speed: flies at up to 200 mph (320 km). A supernatural being. Hit Points and S.D.C.: not applicable.', '[{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Faerie Speak","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Mathematics: Advanced","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Lore: Faeries & Creatures of Magic","pct":98}]', 'Magic knowledge at 90%: read runes, read mystic symbols, recognize and create magic circles, recognize wards, recognize enchantment, recognize magic items and weapons, and the lore of line walkers, stone masters and spell casting. Communicates by telepathy, empathy and magic as well. Leaves ordinary human skills to its minions and life essences; its own craft is magic, psionics, possession and subterfuge. Education: centuries of study in magic and dimensional travel.', 'Nightvision 1000 ft (310 m); sees the invisible; bio-regenerates 2D6x100 M.D.C. an hour; immune to drugs, poisons, gases, fire, heat and cold, and needs no air. Dimensional teleport (98%) with no limit to any world where it has life essences, England among them, and opens a rift on its own P.P.E. to anywhere it has been. Possesses and reanimates the dead. Teleports itself up to 600 miles (960 km). Summons 2D4 greater essence minions and 6D6 lesser minions, up to three times a day. Holds a ley line nexus in old Somerset near New Camelot, straddling two dimensions there; it can choke the nexus to about 10% of its normal P.P.E. and its lines to about 5%, keeping the energy for its essences, and release it for rifts, summonings, ceremonies or its own use. Vulnerability: psionics, supernatural beings, creatures of magic and magic weapons (rune, holy, techno-wizard and most other magic items) do full damage, and Millennium Tree wands, staves and weapons do triple. It must feed on plentiful magic energy and would have to move on if its source waned or were taken. Reduced to 0 M.D.C. it is hurt and impaired (two physical or psionic attacks, one magic, and no combat or save bonuses); it is destroyed only at -500.', 'Equal to a 10th level practitioner of magic with 8000 P.P.E. All Ley Line Walker powers and spells, Stone Master powers (Rifts Atlantis), and the temporal spells Temporal: Time Warp: Space & Time (printed as time and space teleportation), Temporal: Time Barrier, Temporal: Time Maelstrom, Temporal: Time Capsule and Temporal: Time Warp: Age.', 'Equal to a 10th level psionic with 2000 I.S.P. Telepathy, Empathy, See Aura, Sense Magic, and every physical and super-psionic power.', NULL, 'None; incompatible with an energy being.', 'None; it fights with energy blasts, magic and psionics.', NULL, 'A patient schemer bent on world conquest, working through puppets: it plays Mrrlyn the kindly sorcerer and has planted other essences of itself in key places in New Camelot. It thinks in eons, and means to take the British Isles and Ireland, then the lands once called France, Spain and Italy. It weighs the NGR as an ally to be subverted, and Atlantis as a tempting target.', 'Its own life essences: Mrrlyn, the Lady of the Lake, Lady Guinevere and the supreme nexus knights.', 'Splynncryth and the Splugorth, ancient rivals of its race; it and Splynncryth have pitted mortal pawns against each other across dimensions before.', 'The Zllyphan intelligence whose splintered essences include Mrrlyn. In its own form it is a house-sized globe of blue and white energy, and it stays half outside Earth through the nexus it controls. Long ago its Camelot fell apart as the magic faded and its Mrrlyn essence was sealed in a crystal chamber underground; the return of the ley lines woke it, and the scheme has begun again. (p.85-86)', 'Rifts World Book 3: England p.85-86'),
('mrrlyn', 'Mrrlyn', 'Zazshan (a splintered life essence of it)', 'The Enchanter, mentor and counselor to King Arr''thuu', 'rifts', 'Zllyphan greater life essence in a human body', '7th level spell caster and 7th level mind mage (Zllyphan greater life essence)', 7, 'Miscreant (Alter Aura makes him read as Scrupulous and human)', 'Looks about 50; really 120', '6 feet, 2 inches (1.8 m)', NULL, '{"IQ":22,"ME":21,"MA":15,"PS":30,"PP":22,"PE":28,"PB":9,"Spd":18}', NULL, NULL, 2000, 800, 350, NULL, 14, '{"attacks":6,"initiative":6,"strike":6,"dodge":6}', 'Six hand to hand or psionic attacks per melee, or attacks by magic. The +6 to strike is in hand to hand; +3 to strike with an energy weapon or gun. +6 to save vs Horror Factor, +1 to spell strength, +2 on all saving throws (on top of attribute bonuses); impervious to mind control, even a vampire''s. These bonuses are the same for every greater life essence. Supernatural P.S. and P.E., which he takes care to hide. His mental attributes are 25% below the intelligence''s. A supernatural being. Hit Points and S.D.C.: not applicable. Male.', '[{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Faerie Speak","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Mathematics: Basic","pct":93},{"name":"Mathematics: Advanced","pct":93},{"name":"Astronomy","pct":73},{"name":"Lore: Demons & Monsters","pct":73},{"name":"Lore: Faeries & Creatures of Magic","pct":73},{"name":"Chemistry","pct":68},{"name":"Forgery","pct":68},{"name":"Escape Artist","pct":78},{"name":"Disguise","pct":73},{"name":"Intelligence","pct":74},{"name":"Prowl","pct":73},{"name":"Palming","pct":68},{"name":"Pick Locks","pct":78},{"name":"Streetwise","pct":62},{"name":"Swimming","pct":88},{"name":"Horsemanship: General","pct":72}]', 'Magic knowledge at 90%, as Zazshan''s: read runes, read mystic symbols, recognize and create magic circles, recognize wards, recognize enchantment, recognize magic items and weapons, and the lore of line walkers, stone masters and spell casting. The book prints the skills as basic and advanced math, astronomy, demon and monster lore, faerie lore, swim and horsemanship. A greater essence may learn up to 14 skills at its own level, and only skills of magic, cunning and deception (forgery, palming, escape) take a 10% bonus plus the I.Q. bonus. A possessing essence can pick up as many as four local languages, usually forgotten later. Education: as the alien intelligence.', 'Nightvision 100 ft (30.5 m); sees the invisible; bio-regenerates 2D6x10 M.D.C. an hour; takes half damage from cold, heat, fire, gases, drugs and poisons. The host body eats about a tenth of what a human does, sleeps or meditates three hours a day and tires at a tenth the human rate; it lasts about ten times a normal span, roughly 700 years. Dimensional teleport (98%) with no limit back to the intelligence''s home dimension. Arriving in a new dimension as a chair-sized energy globe, the essence has 24 hours to possess and reanimate a corpse or it is pulled back to the intelligence. At 0 M.D.C. the body is destroyed and the essence is driven out as a sphere of 1D4x100 M.D.C.; it then has 12 hours to take a new body or it returns home and cannot come back for 2D6 months. Cannot be magically transformed (metamorphosis fails), though illusions such as Mask of Deceit and Multiple Images work. Vulnerability: psionics, magic weapons, supernatural beings and creatures of magic all do normal damage, and Millennium Tree wands, staves and weapons do triple. Average major life essence, for reference: P.S. 3D6+12, P.P. 3D6+6, P.E. 3D6+12, P.B. 3D6, Spd 5D6 as a human, 2D6x10 mph flying as energy; 1D4x1000 M.D.C.; Horror Factor 14; P.P.E. 2D6x100; I.S.P. 1D4x100+50; typically 5th to 9th level. Lesser essences such as the supreme nexus knights have 2D6x10 P.P.E. and 3D4x10 I.S.P.', '7th level spell caster with 800 P.P.E. Everything the intelligence knows: all Ley Line Walker powers and spells of levels 1-15, Stone Master powers (Rifts Atlantis), and the temporal spells Temporal: Time Warp: Space & Time (printed as time and space teleportation), Temporal: Time Barrier, Temporal: Time Maelstrom, Temporal: Time Capsule and Temporal: Time Warp: Age.', 'Master psionic, equal to a 7th level mind mage, with 350 I.S.P. Telepathy, Empathy, See Aura, Sense Magic, every physical power, and nine super-psionic powers fixed once chosen: Bio-Manipulation (the evil eye), Empathic Transmission, Group Mind Block, Mind Block Auto-Defense, Hypnotic Suggestion, Mind Wipe, Psi-Shield, Psi-Sword and Pyrokinesis. Uses Alter Aura to pass as good and human.', NULL, 'None; he would never consider them.', 'Relies on magic and psionics. Usually carries a silver dagger and has been known to use an energy pistol; otherwise he prefers magic items. Any armor he wears is for show or disguise. His sanctum is a hidden cave on the western coast of Wales, guarded by wards of alarm and three powerful rune statues, where he retreats to meditate and to work secret rituals and dangerous magic.', '30 million credits, 140 million in pre-Rifts artifacts and 20 million in precious metals and gems; half of the fortune is hidden in his Welsh lair.', 'Plays the benevolent sorcerer while serving the intelligence''s plan of conquest. He has raised Camelot again around a noble young king he means to use as a playing piece, gathers knights and champions who will trust him blindly, and paints rival kingdoms as monstrous or tyrannical so that they can be attacked with a clear conscience. Patient, since he expects the magic to last for eons.', 'Zazshan and its other essences: the Lady of the Lake, Lady Guinevere and the supreme nexus knights; the nexus knights he raised; King Arr''thuu, unaware.', 'Splynncryth and the Splugorth; any kingdom standing in New Camelot''s way.', 'New Camelot''s enchanter and the king''s counselor, in truth a fragment of the alien intelligence Zazshan wearing a reanimated human body. He ruled through an earlier Camelot until the magic ebbed, was trapped in a crystal chamber deep underground, and woke when the ley lines returned. He looks like a white-haired, white-bearded man of about fifty, often with a ponytail, in silk robes and cloaks. (p.86-89)', 'Rifts World Book 3: England p.86-89'),
('lady-of-the-lake', 'The Lady of the Lake', 'Zazshan (a splintered life essence of it)', 'The Lady, supposed protector of the British Isles', 'rifts', 'Zllyphan greater life essence in a human body', '7th level spell caster and 7th level mind mage (Zllyphan greater life essence)', 7, 'Miscreant (Alter Aura makes her read as Scrupulous)', 'Looks about 20; really 50', '6 feet (1.8 m)', NULL, '{"IQ":22,"ME":21,"MA":15,"PS":30,"PP":22,"PE":28,"PB":20,"Spd":21}', NULL, NULL, 3000, 900, 350, NULL, 14, '{"attacks":6,"initiative":6,"strike":6,"dodge":6}', 'Six hand to hand or psionic attacks per melee, or attacks by magic. The +6 to strike is in hand to hand; +3 to strike with an energy weapon or gun. +6 to save vs Horror Factor, +1 to spell strength, +2 on all saving throws (on top of attribute bonuses); impervious to mind control, even a vampire''s. Horror Factor from her supernatural powers. Supernatural P.S. and P.E. A supernatural being. Hit Points and S.D.C.: not applicable. Female.', '[{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Faerie Speak","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Mathematics: Basic","pct":93},{"name":"Mathematics: Advanced","pct":93},{"name":"Astronomy","pct":73},{"name":"Lore: Demons & Monsters","pct":73},{"name":"Lore: Faeries & Creatures of Magic","pct":73},{"name":"Identify Plants & Fruit","pct":63},{"name":"Track & Trap Animals","pct":58},{"name":"Intelligence","pct":74},{"name":"Wilderness Survival","pct":68},{"name":"Land Navigation","pct":68},{"name":"Navigation","pct":88},{"name":"Prowl","pct":73},{"name":"Palming","pct":68},{"name":"Pick Pockets","pct":73},{"name":"Streetwise","pct":62},{"name":"Swimming","pct":88},{"name":"Horsemanship: General","pct":72}]', 'Magic knowledge, languages and literacy as Mrrlyn''s: the magic lore skills at 90%. The book prints track animals, swim and horsemanship. Education: as the alien intelligence.', 'As Mrrlyn''s: nightvision 100 ft (30.5 m), sees the invisible, bio-regenerates 2D6x10 M.D.C. an hour, half damage from cold, heat, fire, gases, drugs and poisons; eats a tenth of a human''s fare, needs three hours of sleep or meditation and tires at a tenth the human rate; the body lasts about 700 years. Can return to the intelligence''s home dimension at will by dimensional teleport (98%); must take a corpse within 24 hours of reaching a new dimension. At 0 M.D.C. the body is destroyed and the essence flees as a 1D4x100 M.D.C. sphere with 12 hours to find a new host, or it goes home for 2D6 months. Cannot be magically transformed; illusions work on her. Vulnerability: psionics, magic weapons, supernatural beings and creatures of magic all do normal damage; Millennium Tree wands, staves and weapons do triple. Seen swimming underwater, floating over and walking on water, and on land within a few hundred yards of it.', '7th level spell caster with 900 P.P.E. As Mrrlyn: all Ley Line Walker powers and spells of levels 1-15, Stone Master powers (Rifts Atlantis), and Temporal: Time Warp: Space & Time (printed as time and space teleportation), Temporal: Time Barrier, Temporal: Time Maelstrom, Temporal: Time Capsule and Temporal: Time Warp: Age.', 'Master psionic, equal to a 7th level mind mage, with 350 I.S.P. Telepathy, Empathy, See Aura, Sense Magic, every physical power, and nine super-psionic powers fixed once chosen: Empathic Transmission, Electrokinesis, Hydrokinesis, Telekinesis (Super), Mind Bolt, Mentally Possess Others, Group Mind Block, Mind Block Auto-Defense and Psi-Sword. Uses Alter Aura to pass as good.', NULL, 'None.', 'None; she relies entirely on magic and psionics. Body armor: none. Shares Mrrlyn''s secret lair in Wales, where the two meet to plan.', 'None of her own; she can draw on Mrrlyn''s hoard, and passes him in secret any wealth she comes by.', 'Presents herself as a kindly, independent spirit of nature and light who rescues the drowning, warns travellers of danger and advises good folk. The trust she earns is the point: people confide in her, and everything they tell her goes to Zazshan and Mrrlyn.', 'Zazshan, Mrrlyn and the other essences, in secret; publicly helps Mrrlyn and King Arr''thuu now and then.', 'Whoever threatens the intelligence''s plans.', 'Wilderness folk take her for a water nymph or nature spirit guarding Britain; she is said to live at the White Lake but turns up at waters across the isles, and she gave King Arr''thuu the psionic sword Caliber X. In truth she is another essence of Zazshan, kept apart from Mrrlyn so she can step in as the good side''s adviser if he falls. Tall and pale, with long blond hair and white or blue gowns. (p.89-90)', 'Rifts World Book 3: England p.89-90'),
('lady-guinevere', 'Lady Guinevere', 'Zazshan (a splintered life essence of it)', 'Consort to King Arr''thuu', 'rifts', 'Zllyphan greater life essence in a human body', '7th level spell caster and 7th level mind mage (Zllyphan greater life essence)', 7, 'Miscreant (Alter Aura makes her read as Scrupulous and fully human)', 'Looks 20; really 10', '5 feet, 6 inches (1.55 m, as printed)', NULL, '{"IQ":22,"ME":21,"MA":15,"PS":30,"PP":22,"PE":28,"PB":19,"Spd":17}', NULL, NULL, 1000, 600, 550, NULL, 14, '{"attacks":6,"initiative":6,"strike":6,"dodge":6}', 'Six hand to hand or psionic attacks per melee, or attacks by magic. The +6 to strike is in hand to hand; +3 to strike with an energy weapon or gun. +6 to save vs Horror Factor, +1 to spell strength, +2 on all saving throws (on top of attribute bonuses); impervious to mind control, even a vampire''s. Horror Factor from her supernatural powers. Supernatural P.S. and P.E., which she hides. A supernatural being. Hit Points and S.D.C.: not applicable. Female.', '[{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Faerie Speak","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Mathematics: Basic","pct":93},{"name":"Mathematics: Advanced","pct":93},{"name":"Lore: Demons & Monsters","pct":73},{"name":"Lore: Faeries & Creatures of Magic","pct":73},{"name":"Dance","pct":73},{"name":"Play Musical Instrument: Flute","pct":73},{"name":"Play Musical Instrument: Mandolin","pct":73},{"name":"Cook","pct":73},{"name":"Identify Plants & Fruit","pct":63},{"name":"Preserve Food","pct":75},{"name":"Intelligence","pct":74},{"name":"Disguise","pct":73},{"name":"Prowl","pct":73},{"name":"Palming","pct":68},{"name":"Pick Pockets","pct":73},{"name":"Streetwise","pct":62},{"name":"Horsemanship: General","pct":72}]', 'Magic knowledge, languages and literacy as Mrrlyn''s: the magic lore skills at 90%. The book prints play flute, play mandolin and horsemanship. Education: as the alien intelligence.', 'As Mrrlyn''s: nightvision 100 ft (30.5 m), sees the invisible, bio-regenerates 2D6x10 M.D.C. an hour, half damage from cold, heat, fire, gases, drugs and poisons; eats a tenth of a human''s fare, needs three hours of sleep or meditation and tires at a tenth the human rate; the body lasts about 700 years. Can return to the intelligence''s home dimension at will by dimensional teleport (98%); must take a corpse within 24 hours of reaching a new dimension. At 0 M.D.C. the body is destroyed and the essence flees as a 1D4x100 M.D.C. sphere with 12 hours to find a new host, or it goes home for 2D6 months. Cannot be magically transformed; illusions work on her. Vulnerability: psionics, magic weapons, supernatural beings and creatures of magic all do normal damage; Millennium Tree wands, staves and weapons do triple.', '7th level spell caster with 600 P.P.E., though the court believes her a first or second level Ley Line Walker studying under Mrrlyn. As Mrrlyn: all Ley Line Walker powers and spells of levels 1-15, Stone Master powers (Rifts Atlantis), and Temporal: Time Warp: Space & Time (printed as time and space teleportation), Temporal: Time Barrier, Temporal: Time Maelstrom, Temporal: Time Capsule and Temporal: Time Warp: Age.', 'Master psionic, equal to a 7th level mind mage, with 550 I.S.P.; the court thinks her only slightly psychic. Telepathy, Empathy, See Aura, Sense Magic, every physical power, and super-psionic powers fixed once chosen: Empathic Transmission, Telekinesis (Super), Hypnotic Suggestion, Mentally Possess Others, Mind Wipe, Mind Bond, Mind Block Auto-Defense and Psi-Sword. The book says nine and lists telekinesis twice, so eight are named. Uses Alter Aura to pass as good and human.', NULL, 'None.', 'None; she relies entirely on magic and psionics. Body armor: none. Shares Mrrlyn''s secret lair in Wales, where they meet to plan.', '200,000 credits of her own; the kingdom pays all her expenses, clothes included, and she can draw on Mrrlyn''s hoard.', 'Acts the sweet, fussy but spirited noblewoman in love with the king, and is careful never to show her real power; the court adores her and fears nothing from her. Her task is to watch King Arr''thuu and steer him without his noticing.', 'Zazshan, Mrrlyn and the other essences, in secret; King Arr''thuu, who loves her.', 'Whoever threatens the intelligence''s plans.', 'A third essence of Zazshan, placed at New Camelot about five years ago. Within a year she and King Arr''thuu were lovers, as Mrrlyn intended; the court already treats her as queen and expects a proposal once the king''s campaigns allow. A pretty young woman with brown hair who dresses as a noble. (p.90-91)', 'Rifts World Book 3: England p.90-91');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('notable_npc', 'zazshan', 'Energy blast', '1D6x10 M.D.', 1, '2000 ft (610 m)', 'Any increment of damage up to the maximum. Six per melee, in energy form.', 0),
('notable_npc', 'mrrlyn', 'Psi-Sword', NULL, 1, NULL, 'Super-psionic power; damage as the Psi-Sword power at 7th level.', 0),
('notable_npc', 'mrrlyn', 'Silver dagger', NULL, 0, NULL, 'No damage printed in his block.', 1),
('notable_npc', 'mrrlyn', 'Energy pistol', NULL, 1, NULL, 'No model or damage printed; he has been known to use one.', 2),
('notable_npc', 'lady-of-the-lake', 'Psi-Sword', NULL, 1, NULL, 'Super-psionic power; damage as the Psi-Sword power at 7th level.', 0),
('notable_npc', 'lady-guinevere', 'Psi-Sword', NULL, 1, NULL, 'Super-psionic power; damage as the Psi-Sword power at 7th level.', 0);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 notable NPCs are in' AS assertion, count(*) AS got, 4 AS want
  FROM notable_npcs WHERE slug IN ('zazshan', 'mrrlyn', 'lady-of-the-lake', 'lady-guinevere');
SELECT 'and the notables 6' AS assertion, count(*) AS got, 6 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('zazshan', 'mrrlyn', 'lady-of-the-lake', 'lady-guinevere');

